import{_ as t,o as d,c as a,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/DESCRIPTIVES.md","filePath":"manual-en/DESCRIPTIVES.md","lastUpdated":1785684581000}'),i={name:"manual-en/DESCRIPTIVES.md"};function o(r,e,n,c,p,h){return d(),a("div",null,[...e[0]||(e[0]=[s(`<h3 id="_15-1-descriptives" tabindex="-1">15.1 DESCRIPTIVES <a class="header-anchor" href="#_15-1-descriptives" aria-label="Permalink to &quot;15.1 DESCRIPTIVES&quot;">​</a></h3><pre><code>DESCRIPTIVES
        /VARIABLES=var_list
        /MISSING={VARIABLE,LISTWISE} {INCLUDE,NOINCLUDE}
        /FORMAT={LABELS,NOLABELS} {NOINDEX,INDEX} {LINE,SERIAL}
        /SAVE
        /STATISTICS={ALL,MEAN,SEMEAN,STDDEV,VARIANCE,KURTOSIS,
                     SKEWNESS,RANGE,MINIMUM,MAXIMUM,SUM,DEFAULT,
                     SESKEWNESS,SEKURTOSIS}
        /SORT={NONE,MEAN,SEMEAN,STDDEV,VARIANCE,KURTOSIS,SKEWNESS,
               RANGE,MINIMUM,MAXIMUM,SUM,SESKEWNESS,SEKURTOSIS,NAME}
              {A,D}
</code></pre><p>The <code>DESCRIPTIVES</code> procedure reads the active dataset and outputs linear descriptive statistics requested by the user. In addition, it can optionally compute Z-scores.</p><p>The <code>VARIABLES</code> subcommand, which is required, specifies the list of variables to be analyzed. Keyword <code>VARIABLES</code> is optional.</p><p>All other subcommands are optional:</p><p>The <code>MISSING</code> subcommand determines the handling of missing variables. If <code>INCLUDE</code> is set, then user-missing values are included in the calculations. If <code>NOINCLUDE</code> is set, which is the default, user-missing values are excluded. If <code>VARIABLE</code> is set, then missing values are excluded on a variable by variable basis; if <code>LISTWISE</code> is set, then the entire case is excluded whenever any value in that case has a system-missing or, if <code>INCLUDE</code> is set, user-missing value.</p><p>The <code>FORMAT</code> subcommand has no effect. It is accepted for backward compatibility.</p><p>The <code>SAVE</code> subcommand causes <code>DESCRIPTIVES</code> to calculate Z scores for all the specified variables. The Z scores are saved to new variables. Variable names are generated by trying first the original variable name with Z prepended and truncated to a maximum of 8 characters, then the names ZSC000 through ZSC999, STDZ00 through STDZ09, ZZZZ00 through ZZZZ09, ZQZQ00 through ZQZQ09, in that sequence. In addition, Z score variable names can be specified explicitly on <code>VARIABLES</code> in the variable list by enclosing them in parentheses after each variable. When Z scores are calculated, PSPP ignores <code>TEMPORARY</code>, treating temporary transformations as permanent.</p><p>The <code>STATISTICS</code> subcommand specifies the statistics to be displayed:</p><p><code>ALL</code></p><p>All of the statistics below.</p><p><code>MEAN</code></p><p>Arithmetic mean.</p><p><code>SEMEAN</code></p><p>Standard error of the mean.</p><p><code>STDDEV</code></p><p>Standard deviation.</p><p><code>VARIANCE</code></p><p>Variance.</p><p><code>KURTOSIS</code></p><p>Kurtosis and standard error of the kurtosis.</p><p><code>SKEWNESS</code></p><p>Skewness and standard error of the skewness.</p><p><code>RANGE</code></p><p>Range.</p><p><code>MINIMUM</code></p><p>Minimum value.</p><p><code>MAXIMUM</code></p><p>Maximum value.</p><p><code>SUM</code></p><p>Sum.</p><p><code>DEFAULT</code></p><p>Mean, standard deviation of the mean, minimum, maximum.</p><p><code>SEKURTOSIS</code></p><p>Standard error of the kurtosis.</p><p><code>SESKEWNESS</code></p><p>Standard error of the skewness.</p><p>The <code>SORT</code> subcommand specifies how the statistics should be sorted. Most of the possible values should be self-explanatory. <code>NAME</code> causes the statistics to be sorted by name. By default, the statistics are listed in the order that they are specified on the <code>VARIABLES</code> subcommand. The <code>A</code> and <code>D</code> settings request an ascending or descending sort order, respectively.</p><h4 id="_15-1-1-descriptives-example" tabindex="-1">15.1.1 Descriptives Example <a class="header-anchor" href="#_15-1-1-descriptives-example" aria-label="Permalink to &quot;15.1.1 Descriptives Example&quot;">​</a></h4><p>The physiology.sav file contains various physiological data for a sample of persons. Running the <code>DESCRIPTIVES</code> command on the variables <strong>height</strong> and <strong>temperature</strong> with the default options allows one to see simple linear statistics for these two variables. In Example 15.1, these variables are specfied on the <code>VARIABLES</code> subcommand and the <code>SAVE</code> option has been used, to request that Z scores be calculated.</p><p>After the command has completed, this example runs <code>DESCRIPTIVES</code> again, this time on the <strong>zheight</strong> and <strong>ztemperature</strong> variables, which are the two normalized (Z-score) variables generated by the first <code>DESCRIPTIVES</code> command.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;physiology.sav&#39;.  descriptives         /variables = height temperature         /save.  descriptives         /variables = zheight ztemperature.</span></span></code></pre></div><p><strong>Example 15.1:</strong> Running two <code>DESCRIPTIVES</code> commands, one with the <code>SAVE</code> subcommand</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>Screenshot 15.1:</strong> The Descriptives dialog box with two variables and Z-Scores option selected</p><p>In Result 15.1, we can see that there are 40 valid data for each of the variables and no missing values. The mean average of the height and temperature is 16677.12 and 37.02 respectively. The descriptive statistics for temperature seem reasonable. However there is a very high standard deviation for <strong>height</strong> and a suspiciously low minimum. This is due to a data entry error in the data (see <a href="./Identifying-incorrect-data">Identifying incorrect data</a>).</p><p>In the second Descriptive Statistics command, one can see that the mean and standard deviation of both Z score variables is 0 and 1 respectively. All Z score statistics should have these properties since they are normalized versions of the original scores.</p><table tabindex="0"><thead><tr><th></th><th>N</th><th>Mean</th><th>Std Dev</th><th>Minimum</th><th>Maximum</th></tr></thead><tbody><tr><td>Source</td><td>Target</td><td></td><td></td><td></td><td></td></tr><tr><td>Height in millimeters</td><td>Zheight</td><td></td><td></td><td></td><td></td></tr><tr><td>Internal body temperature in degrees Celcius</td><td>Ztemperature</td><td></td><td></td><td></td><td></td></tr><tr><td>Height in millimeters</td><td>40</td><td>1677.12</td><td>262.87</td><td>179</td><td>1903</td></tr><tr><td>Internal body temperature in degrees Celcius</td><td>40</td><td>37.02</td><td>1.82</td><td>32.59</td><td>39.97</td></tr><tr><td>Valid N (listwise)</td><td>40</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>N</td><td>Mean</td><td>Std Dev</td><td>Minimum</td><td>Maximum</td></tr><tr><td>Z-score of Height in millimeters</td><td>40</td><td>1.93E-015</td><td>1.00</td><td>-5.70</td><td>.86</td></tr><tr><td>Z-score of Internal body temperature in degrees Celcius</td><td>40</td><td>1.37E-015</td><td>1.00</td><td>-2.44</td><td>1.62</td></tr><tr><td>Valid N (listwise)</td><td>40</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Result 15.1:</strong> Descriptives statistics including two normalized variables (Z-scores)</p>`,49)])])}const S=t(i,[["render",o]]);export{m as __pageData,S as default};
